N = 110
w = [[0] * N for _ in range(N)]
sum_w = [[0] * N for _ in range(N)]
def main():
    n, m, k = map(int, input().split())
    for i in range(1, n+1):
        s = input()
        for j in range(1, m+1):
            w[i][j] = int(s[j-1])
            sum_w[i][j] = sum_w[i][j-1] + w[i][j]
    ans = 0
    for i in range(1, m+1):
        for j in range(i, m+1):
            num = []
            now = 0
            for l in range(1, n+1):
                tmp = sum_w[l][j] - sum_w[l][i-1]
                now += tmp
                num.append(now)
                if now >= k:
                    if ans == 0:
                        ans = (j-i+1) * l
                    else:
                        ans = min(ans, (j-i+1) * l)
                    L, R = 1, l
                    while L < R:
                        mid = (L + R + 1) // 2
                        if now - num[mid-1] >= k:
                            L = mid
                        else:
                            R = mid - 1
                    if now - num[L-1] >= k:
                        if ans == 0:
                            ans = (j-i+1) * (l-L)
                        else:
                            ans = min(ans, (j-i+1) * (l-L))
    print(ans)
if __name__ == "__main__":
    main()

N = 10**5 + 10
a = [0] * N
def calc(x):
    i = 2
    mp = {}
    while i * i <= x:
        if x % i == 0:
            mp[i]=1
            while x % i == 0:
                x //= i
        i += 1
    if x != 1:
        mp[x]=1
    return int(len(mp.items()))
def main():
    n = int(input())

    for i in range(1, n + 1):
        a[i] = int(input())
        x = calc(a[i])
        if x == 2:
            print("1")
        else:
            print("0")
